import { useState } from 'react';
import { Input, Button, Toast } from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const [email, setEmail] = useState('');
  const [showToast, setShowToast] = useState(false);

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!email) return;

    setEmail('');
    setShowToast(true);
  };

  return (
    <div className="jx-stack" style={{ position: 'relative' }}>
      <form onSubmit={handleSubmit} className="jx-stack jx-stack--horizontal">
        <Input
          type="email"
          name="email"
          placeholder="Введите ваш email"
          value={email}
          onChange={(e: React.ChangeEvent<HTMLInputElement>) => setEmail(e.target.value)}
          required
          className="jx-input"
        />
        <Button type="submit" className="jx-button jx-button--primary">
          Подписаться
        </Button>
      </form>

      {showToast && (
        <Toast
          className="jx-toast jx-toast--corner"
          title="Готово"
          description="Письмо с подтверждением подписки отправлено на ваш email."
          onClose={() => setShowToast(false)}
        />
      )}
    </div>
  );
}

